cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/travel_expenses.xlsx');
const ws = wb.Sheets['Travel'];

// Get current range to find next row
const range = XLSX.utils.decode_range(ws['!ref']);
const nextRow = range.e.r + 1; // 0-indexed

const newRecords = [
  ['FL658038', 'Maya Thompson', 'Flight', 'JFK → LHR', '', 'pending', 0],
  ['HR-A1B2',  'Maya Thompson', 'Hotel',  'Desert Palm Hotel, Las Vegas', '', 'pending', 0],
  ['CR-C3D4',  'Maya Thompson', 'Car Rental', 'Las Vegas McCarran International Airport → Las Vegas McCarran International Airport', '', 'pending', 0]
];

const cols = ['A','B','C','D','E','F','G'];
newRecords.forEach((rec, ri) => {
  rec.forEach((val, ci) => {
    ws[cols[ci] + (nextRow + ri + 1)] = { v: val, t: typeof val === 'number' ? 'n' : 's' };
  });
});

// Update the range
range.e.r = nextRow + newRecords.length - 1;
ws['!ref'] = XLSX.utils.encode_range(range);

XLSX.writeFile(wb, 'testbed/data/travel_expenses.xlsx');
console.log('File updated. Verifying...');

// Re-read and print last rows to confirm
const wb2 = XLSX.readFile('testbed/data/travel_expenses.xlsx');
const data = XLSX.utils.sheet_to_json(wb2.Sheets['Travel'], { header: 1, defval: '' });
console.log('Total rows (incl. header):', data.length);
console.log();
data.slice(-3).forEach((row, i) => console.log('Row ' + (data.length - 2 + i) + ':', JSON.stringify(row)));
"
